// eventPayloadPHIAllowlist is the positive allowlist from
// docs/superpowers/specs/2026-08-14-event-transport-isolation-design.md
// (D4): every payload field, across every contract package, that is
// known to carry clinical or patient-identifying data, keyed
// "<module>.<Type>.<Field>" with the reason it has to be on the wire.
//
// This is deliberately a positive allowlist, not a name-pattern
// denylist. A denylist guesses at names ("Patient*", "*Name"), which
// fails on exactly the field the product needs (this one) and misses
// anything it didn't think to guess — "notes", "reason_for_visit", a
// DOB stored as a timestamp. Every field this test finds is presumed
// PHI-shaped until a human puts it in one of the two maps below; adding
// an entry is therefore a diff a reviewer sees and must justify, not a
// pattern match that can silently start admitting a new field.
var eventPayloadPHIAllowlist = map[string]string{
	"supply.SupplierReceivingResponseExchangeData.Reason":       "bounded supplier response rationale required for hospital discrepancy reconciliation; directed to the exact buyer only, no patient content requested",
	"supply.SupplierReceivingResponseExchangeData.ActorSubject": "authenticated supplier signatory required to attribute a disputed or confirmed receiving response to its source; exact bilateral exchange only",

	"supply.SupplierDispatchRecordedData.HandoffReference":   "bounded transport document reference needed for matching physical custody; restricted bilateral exchange, no patient data requested",
	"supply.SupplierDispatchRecordedData.ActorSubject":       "authenticated physical-operation actor needed for accountable handoff and receiving; exact bilateral exchange only, no contact or private Staff UUID",
	"supply.SupplierShipmentExchangeData.HandoffReference":   "bounded transport document reference needed for matching physical custody; restricted bilateral exchange, no patient data requested",
	"supply.SupplierShipmentExchangeData.ActorSubject":       "authenticated physical-operation actor needed for accountable handoff and receiving; exact bilateral exchange only, no contact or private Staff UUID",
	"pharmacy.SupplierDispatchRecordedData.HandoffReference": "bounded transport document reference needed for matching physical custody; restricted bilateral exchange, no patient data requested",
	"pharmacy.SupplierDispatchRecordedData.ActorSubject":     "authenticated physical-operation actor needed for accountable handoff and receiving; exact bilateral exchange only, no contact or private Staff UUID",
	"supply.ReceivingSummary.Reason":                         "bounded receiving/discrepancy rationale required for supplier reconciliation; restricted bilateral exchange, no patient data requested",
	"supply.ReceivingSummary.ActorSubject":                   "authenticated physical-operation actor needed for accountable handoff and receiving; exact bilateral exchange only, no contact or private Staff UUID",
	"pharmacy.ReceivingSummary.Reason":                       "bounded receiving/discrepancy rationale required for supplier reconciliation; restricted bilateral exchange, no patient data requested",
	"pharmacy.ReceivingSummary.ActorSubject":                 "authenticated physical-operation actor needed for accountable handoff and receiving; exact bilateral exchange only, no contact or private Staff UUID",
	"supply.OrderExchangeData.SignatorySubject":              "authenticated order signatory needed for independent bilateral consent and self-review checks; restricted exact tenant-directed exchange, never broadcast or log",
	"supply.SupplierOrderInput.Reason":                       "shared bounded procurement instructions needed by the exact contracting supplier; no patient data requested; restricted bilateral exchange and audit, never broadcast or log",

	"supply.RelationshipExchangeData.SignatorySubject": "authenticated commercial signatory needed for attributable independent consent and self-review rejection; directed bilateral exchange only, no contacts or identity evidence",

	"iam.SupplierGrantExchangeData.Input":            "immutable grant input includes the nominated account and review rationale; exact bilateral tenant-directed protocol only, never a broadcast or log",
	"iam.SupplierGrantExchangeData.SignatorySubject": "authenticated signatory needed to reject self-acceptance and attribute bilateral consent; restricted directed exchange, no contact or identity documents",
	"iam.SupplierGrantInput.RecipientSubject":        "exact nominated hospital account required to bind named-person consent; directed recipient tenant only, never a supplier membership",
	"iam.SupplierGrantInput.Reason":                  "bounded consent rationale retained for attributable review; restricted bilateral exchange and audit, no clinical purpose or patient data requested",

	"patientmaster.RegistrationReference.PatientID":         "exact known patient reference in authenticated hospital-scoped owner HTTP only, with committed read audit; never published as an event or used as record disclosure authority",
	"mediconnect.ClaimCheckRequest.Relationship":            "exact relationship bound to patient/subject in workload-authenticated private owner HTTP only; never broadcast or logged",
	"mediconnect.ClaimCheckRequest.Subject":                 "exact owner-subject selection in workload-authenticated internal HTTP only; never published as an event",
	"mediconnect.ClaimCheckRequest.PatientID":               "exact patient selection in workload-authenticated internal HTTP only; never published as an event",
	"mediconnect.RegistrationReviewData.RequesterSubject":   "opaque authenticated requester identity is required solely to reject registrar self-review across owners; no contact or identity evidence; restricted same-tenant consumer",
	"pharmacy.AffiliationVerificationData.RequesterSubject": "opaque authenticated requester identity is required solely to reject self-acceptance of a pharmacy affiliation by the hospital; no contact or identity evidence; restricted same-tenant consumer",
	"mediconnect.RegistrationReviewData.Relationship":       "unverified allowlisted relationship claim is necessary for hospital evidence review and immutable request lineage; never proxy authority or consent; no free text",

	"medicore.VisitCreatedData.PatientName": "pharmacy and lab display it on their work queues; modules may not import modules, so there is no cross-module read path to fetch it instead",
}

